\title{Super-Exponential Growth of Symmetric Chain Decomposition Counts:\\
A Bounded-vs-Growing-Arity Dichotomy}
\author{Aristotle}
\date{June 28, 2026}

\begin{document}

\begin{abstract}
We study the \emph{number} of symmetric chain decompositions (SCDs) of graded
posets, a finer invariant than the classical existence question. We isolate a
clean growth predicate, \emph{super-exponentiality}---a sequence
$f:\N\to\N$ is super-exponential if it eventually dominates every fixed
exponential $c^n$---and prove that it is generated by \emph{growing arity of
independent combinatorial choices}. Concretely: (1) the factorial is
super-exponential, hence so is the count of permutations of an $n$-element set;
(2) super-exponentiality transfers upward along eventual pointwise inequalities,
so any factorial-sized lower bound on a count forces super-exponential growth;
(3) a fixed polynomial $m\mapsto m^k$ is \emph{not} super-exponential. We then
exhibit a concrete instance: the two-level ``slab'' poset $\mathrm{CB}(n)$ on
$\{\bottom,\topp\}\times\{1,\dots,n\}$ has at least $n!$ symmetric chain
decompositions, via an explicit injection from the symmetric group, whence its
SCD-count $\numSCD$ is super-exponential. Finally we contrast this with the
blown-up crown $\Crown(w,m)$ of fixed width $w$: its certified floor of $m^{2w}$
strict alternating cycles \emph{diverges} yet is provably \emph{not}
super-exponential. The synthesis theorem packages all three phenomena and
pinpoints the dividing line: super-exponential growth arises precisely when the
number of independent choices grows with the parameter (slab: $n$ matchings
$\Rightarrow n!$), and fails when bounded (crown: $2w$ choices $\Rightarrow
m^{2w}$). This furnishes the structural engine behind the conjecture that
$\#\mathrm{SCD}(M(n))$---and, for fixed $m>1$, $\#\mathrm{SCD}(L(m,n))$---is
super-exponential in $n$. All results are machine-checked.
\end{abstract}

\maketitle

\section{Introduction}

A finite \emph{graded poset} $P$ is a partially ordered set with a rank function
$\rk:P\to\N$ such that covering relations increase rank by one; let
$N=\max_x\rk(x)$ be its top rank. A chain $x_0<x_1<\cdots<x_k$ is
\emph{symmetric} if its ranks are consecutive, $\rk(x_{i+1})=\rk(x_i)+1$, and
balanced about the middle, $\rk(x_0)+\rk(x_k)=N$. A \emph{symmetric chain
decomposition} (SCD) of $P$ is a partition of $P$ into symmetric chains.

Symmetric chain decompositions are a cornerstone of Sperner theory: a poset
admitting an SCD is automatically Sperner, rank-symmetric, rank-unimodal, and has
the strong Sperner property. The \emph{existence} of SCDs has been studied
intensively---for the Boolean lattice, products of chains, and the normalized
matching family.

This paper concerns the finer invariant $\#\mathrm{SCD}(P)$, the \emph{number} of
distinct symmetric chain decompositions. The motivating conjecture, in the
literature on minuscule lattices, asserts that for fixed $m>1$ the count
$\#\mathrm{SCD}(L(m,n))$---where $L(m,n)$ is the lattice of partitions in an
$m\times n$ box---grows \emph{super-exponentially} in $n$. An analogous conjecture
is natural for $M(n)$, the lattice of partitions into distinct parts at most $n$
(equivalently, subsets of $\{1,\dots,n\}$ ranked by their sum).

\subsection{Contributions}
We do not resolve the $L(m,n)$/$M(n)$ conjecture; we build and verify the
\emph{engine} such a proof must run on, and identify the structural mechanism:
\begin{enumerate}
\item a base-uniform definition of super-exponential growth (Definition~\ref{def:se}),
  with the factorial and permutation count clearing it
  (Theorem~\ref{thm:fact}, Corollary~\ref{cor:perm});
\item a \emph{transfer principle} (Lemma~\ref{lem:transfer}) propagating
  super-exponentiality upward along eventual pointwise inequalities;
\item a non-vacuity theorem (Theorem~\ref{thm:poly}): fixed polynomials
  $m\mapsto m^k$ are not super-exponential;
\item a realization (Theorems~\ref{thm:fact-le}--\ref{thm:numscd}): the two-level
  slab $\mathrm{CB}(n)$ has $\numSCD(n)\ge n!$, hence $\numSCD$ is
  super-exponential;
\item a bridge to the catalog crown (Theorems~\ref{thm:crownfloor}--\ref{thm:synth}):
  $\Crown(w,m)$ carries at least $m^{2w}$ strict alternating cycles, a floor that
  diverges yet is not super-exponential, contrasted with the slab.
\end{enumerate}
The throughline is a dichotomy: \emph{bounded arity of independent choices yields
polynomial floors; growing arity yields factorial floors and super-exponential
growth.}

\section{The growth predicate}

\begin{definition}[exponential domination]
A sequence $f:\N\to\N$ \emph{dominates the base-$c$ exponential eventually} if
there is $N$ with $c^n<f(n)$ for all $n\ge N$.
\end{definition}

\begin{definition}[super-exponential, \texttt{SuperExp}]\label{def:se}
$f:\N\to\N$ is \emph{super-exponential} if it dominates every fixed exponential
eventually:
\[
\SuperExp(f)\ :\Longleftrightarrow\ \forall c\in\N,\ \exists N,\ \forall n\ge N,\
c^n<f(n).
\]
\end{definition}

The quantifier order matters: the threshold $N$ may depend on $c$, but a single
$f$ must beat all bases.

\begin{theorem}[\texttt{factorial\_superexp}]\label{thm:fact}
$\SuperExp(n\mapsto n!)$.
\end{theorem}
\begin{proof}[Proof sketch]
Fix $c$. Cast to $\R$ and use $\lim_{n\to\infty}c^n/n!=0$
(\texttt{FloorSemiring.tendsto\_pow\_div\_factorial\_atTop}). Unfolding the metric
limit at tolerance $\varepsilon=1$ yields $N$ with $|c^n/n!|<1$ for $n\ge N$, i.e.
$c^n/n!<1$; since $n!>0$, $c^n<n!$ over $\R$, and descend to $\N$ by an
order-preserving cast.
\end{proof}

\begin{corollary}[\texttt{perm\_card\_superexp}]\label{cor:perm}
The permutation count $n\mapsto |\Perm(\Fin n)|=n!$ is super-exponential.
\end{corollary}

\begin{lemma}[transfer principle, \texttt{SuperExp.of\_eventually\_le}]\label{lem:transfer}
If $\SuperExp(f)$ and there is $M$ with $f(n)\le g(n)$ for all $n\ge M$, then
$\SuperExp(g)$.
\end{lemma}
\begin{proof}[Proof sketch]
Fix $c$; get $N$ with $c^n<f(n)$ for $n\ge N$. For $n\ge\max(N,M)$,
$c^n<f(n)\le g(n)$.
\end{proof}

\begin{theorem}[non-vacuity, \texttt{pow\_const\_not\_superexp}]\label{thm:poly}
For every fixed $k\in\N$, $\neg\,\SuperExp(m\mapsto m^k)$.
\end{theorem}
\begin{proof}[Proof sketch]
Take a base $c\ge 2$. Then $c^m$ eventually exceeds $m^k$ for all large $m$, so no
threshold makes $m^k>c^m$ persistently; the super-exponential clause fails for
this $c$.
\end{proof}

\section{Symmetric chains on a two-level slab}

\begin{definition}[two-level slab $\mathrm{CB}(n)$]\label{def:slab}
Let the carrier be $\mathrm{CB}(n)=\{\bottom,\topp\}\times\{1,\dots,n\}$ (formally
$\mathrm{Bool}\times\Fin n$), with order generated by $(\bottom,i)<(\topp,j)$ for
all $i,j$ and incomparability within levels. It is graded with ranks $0,1$ and top
rank $N=1$.
\end{definition}

In a two-rank graded poset a symmetric chain is a two-element chain
$(\bottom,i)<(\topp,j)$ (consecutive ranks $0,1$; balanced since $0+1=N$).
Therefore an SCD of $\mathrm{CB}(n)$ is exactly a perfect matching of $K_{n,n}$
between the levels, and these are in bijection with permutations of
$\{1,\dots,n\}$.

\begin{definition}[\texttt{numSCD}]\label{def:numscd}
$\numSCD(n)$ is the number of symmetric chain decompositions of $\mathrm{CB}(n)$.
\end{definition}

\section{The slab is super-exponential}

Define $\texttt{permChains}:\Perm(\Fin n)\to\mathrm{SCD}(\mathrm{CB}(n))$ sending
$\sigma$ to the decomposition with chains $\{(\bottom,i),(\topp,\sigma(i))\}$.
Each is a valid SCD, and the map is injective.

\begin{theorem}[factorial floor, \texttt{factorial\_le\_numSCD}]\label{thm:fact-le}
$n!\le\numSCD(n)$.
\end{theorem}
\begin{proof}[Proof sketch]
$\texttt{permChains}$ injects a set of size $|\Perm(\Fin n)|=n!$ into the set
counted by $\numSCD(n)$; \texttt{Finset.card\_le\_card\_of\_injOn} gives the bound.
\end{proof}

\begin{theorem}[\texttt{numSCD\_superexp}]\label{thm:numscd}
$\SuperExp(\numSCD)$.
\end{theorem}
\begin{proof}
Combine Theorem~\ref{thm:fact-le} (for all $n$) with Theorem~\ref{thm:fact} via
Lemma~\ref{lem:transfer}.
\end{proof}

\begin{remark}[sharpness; Conjecture~\ref{conj:exact}]
$\texttt{permChains}$ is in fact a bijection, so one expects $\numSCD(n)=n!$
exactly; only the inequality is formalized. The super-exponential conclusion needs
only the inequality.
\end{remark}

\section{A foil: the blown-up crown}

\begin{definition}[blown-up crown and strict alternating cycles]\label{def:crown}
Fix width $w\ge 1$ and clone count $m$. The blown-up crown has carrier
$\Crown(w,m)=\Fin w\times\mathrm{Bool}\times\Fin m$ (column, side $a$/$b$, clone),
ordered so lower vertices of column $i$ relate to upper vertices of column $i+1$
around a $w$-cycle, every vertex fattened into a length-$m$ chain. A \emph{strict
alternating cycle} is an indexed family $p:\Fin w\to\Crown(w,m)\times\Crown(w,m)$
satisfying the predicate $\IsStrictAltCycle$.
\end{definition}

Catalog facts: $|\Crown(w,m)|=2wm$ (\texttt{Crown.card}) and the width of
$\Crown(w,m)$ is exactly $w$, independent of $m$ (\texttt{Crown.hasWidth}).

\begin{theorem}[crown floor, \texttt{crown\_strictAltCycle\_card\_lower}]\label{thm:crownfloor}
The number of strict alternating cycles of $\Crown(w,m)$ is at least $m^{2w}$:
\[
m^{2w}\ \le\ \bigl|\{\,p:\Fin w\to\Crown(w,m)^2 \mid \IsStrictAltCycle(p)\,\}\bigr|.
\]
\end{theorem}
\begin{proof}[Proof sketch]
For clone-assignments $u,v:\Fin w\to\Fin m$ the family $\mathrm{cyc}(u,v)$ is a
strict alternating cycle, and $(u,v)\mapsto\mathrm{cyc}(u,v)$ is injective; the
domain has $m^{2w}$ elements.
\end{proof}

\section{The crown bridge: diverging but not exploding}

\begin{definition}[\texttt{crownAltCount}]\label{def:cac}
For $w\neq 0$,
$\crownAltCount(w,m)=\bigl|\{\,p:\Fin w\to\Crown(w,m)^2\mid\IsStrictAltCycle(p)\,\}\bigr|$.
\end{definition}

\begin{lemma}[\texttt{pow\_le\_crownAltCount}]\label{lem:cac}
$m^{2w}\le\crownAltCount(w,m)$.
\end{lemma}

\begin{theorem}[diverge-but-don't-explode]\label{thm:crownbridge}
Fix $w\neq 0$.
\begin{enumerate}
\item[(a)] \emph{(\texttt{crownAltCount\_tendsto\_atTop})}
  $\crownAltCount(w,\cdot)\to\infty$ as $m\to\infty$.
\item[(b)] \emph{(\texttt{crown\_floor\_not\_superexp})}
  $\neg\,\SuperExp(m\mapsto m^{2w})$.
\end{enumerate}
\end{theorem}
\begin{proof}
(a) $w\ge 1\Rightarrow 2w\ge 1$, so $m^{2w}\to\infty$; by Lemma~\ref{lem:cac} the
larger sequence diverges (\texttt{tendsto\_atTop\_mono}, \texttt{tendsto\_pow\_atTop}).
(b) Theorem~\ref{thm:poly} with $k=2w$.
\end{proof}

\begin{theorem}[synthesis, \texttt{scd\_strictly\_outgrows\_crown\_floor}]\label{thm:synth}
For fixed $w\neq 0$,
\[
\SuperExp(\numSCD)\ \wedge\ \neg\,\SuperExp(m\mapsto m^{2w})\ \wedge\
\crownAltCount(w,\cdot)\to\infty.
\]
\end{theorem}
\begin{proof}
Conjoin Theorem~\ref{thm:numscd}, Theorem~\ref{thm:crownbridge}(b), and
Theorem~\ref{thm:crownbridge}(a).
\end{proof}

\section{The dichotomy}

The proofs of Theorem~\ref{thm:crownfloor} and Theorem~\ref{thm:fact-le} are
structurally identical---both count independent choices via an injection from a
product of finite sets---yet land on opposite sides of the super-exponential line.
The difference is \emph{arity}.

\begin{center}
\begin{tabular}{llll}
\hline
Object & Independent choices & Floor & Growth class \\
\hline
Crown $\Crown(w,m)$ & $2w$ columns (fixed) & $m^{2w}$ & polynomial; not super-exp \\
Slab $\mathrm{CB}(n)$ & $\sim n$ matchings (grows) & $n!$ & super-exponential \\
\hline
\end{tabular}
\end{center}

\noindent\textbf{Dividing line.} Super-exponential growth of an
independent-choice count occurs iff the number of choices grows with the
parameter. For $M(n)$ (subsets of $\{1,\dots,n\}$ ranked by sum) the central ranks
grow and their bipartite comparability graph is dense, so a central pair behaves
like a fat two-level slab; Theorem~\ref{thm:numscd}'s mechanism then predicts
$\#\mathrm{SCD}(M(n))$ is super-exponential. The same applies to $L(m,n)$ for
fixed $m>1$.

\section{Future directions}

\begin{conjecture}[exact slab count]\label{conj:exact}
$\numSCD(n)=n!$ exactly. The map $\texttt{permChains}$ is surjective: any
partition of $\mathrm{Bool}\times\Fin n$ into two-element symmetric chains yields a
bijection bottom$\to$top, hence a permutation.
\end{conjecture}

\begin{conjecture}[product lower bound]
If a graded poset $P$ contains $k$ disjoint full equal-level slabs with level
sizes $s_1,\dots,s_k$, then $\#\mathrm{SCD}(P)\ge\prod_t s_t!$, and if
$\max_t s_t\to\infty$ then $\#\mathrm{SCD}(P)$ is super-exponential. Chains never
cross between independent slabs, so choices multiply; a multiplicativity lemma
$\prod_t s_t!\le\#\mathrm{SCD}(P)$ plus Lemma~\ref{lem:transfer} finishes.
\end{conjecture}

\begin{conjecture}[$M(n)$ middle slab]
For $M(n)$ the two central rank levels have equal size growing with $n$ and a
dense comparability graph; the induced matching count is super-exponential, hence
$\#\mathrm{SCD}(M(n))$ is super-exponential---in contrast to the bounded arity
$2w$ of the crown, whose floor $m^{2w}$ is provably not super-exponential.
\end{conjecture}

\begin{conjecture}[$L(m,n)$ for fixed $m>1$]
For fixed $m>1$ the minuscule lattice $L(m,n)$ has middle level sizes growing in
$n$, so $\#\mathrm{SCD}(L(m,n))$ is super-exponential in $n$; $L(2,n)$ is
rank-isomorphic to a Catalan-type ballot poset whose central antichains grow.
\end{conjecture}

\section{Discussion}

The results meet Sperner theory (SCDs certify the strong Sperner property), poset
dimension (strict alternating cycles are Trotter's engine; the crown is the
canonical extremal object), and analytic combinatorics (the factorial's
super-exponentiality is driven by $c^n/n!\to 0$). Methodologically the package
gives a reusable recipe for proving a count explodes: define super-exponentiality
once, prove the factorial clears it once, reduce a target to a factorial lower
bound via an explicit injection, then invoke the transfer principle. The crown
bridge certifies the recipe is discriminating---it does not fire on bounded-arity
constructions---which is why it is the right tool for the $M(n)$ and $L(m,n)$
conjectures. All statements in Sections 2--6 are machine-checked; the conjectures
of Section 8 are explicitly open.

