function THRESHOLD(f, c, limit):
  last_fail <- -1
  for k in 0..limit:
    if not (c^k < f(k)):
      last_fail <- k
  if last_fail == limit: return NONE   # never stably dominated
  return last_fail + 1                  # first N past the last failure

